func payload0(attempt int, endpoint time.Duration) time.Duration {
	if attempt >= retryAttemptCap {
		return maxRetryDelay // attempt is exhausted for this delivery
	}
	backoff := baseRetryDelay << uint(attempt)
	if backoff > maxRetryDelay {
		backoff = maxRetryDelay
	}
	return backoff // dispatcher applies this before deliverOnce
}

